import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'people', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
  {
    path: 'people',
    data: { section: 'people', label: 'People', order: 1 },
    loadComponent: () => import('./features/people/people').then((m) => m.People),
  },
];
import { Component } from '@angular/core';

// The base home page (empty). A page is an Angular component like this one, plus one entry in
// app.routes.ts.
@Component({
  selector: 'app-home',
  template: `<p data-testid="home-empty">Nothing here yet.</p>`,
})
export class Home {}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';

// A person's workflow state, moved forward from DRAFT to REVIEW to FINAL; a FINAL person may be
// reopened to REWORK and moved forward to FINAL again.
export type State = 'DRAFT' | 'REVIEW' | 'FINAL' | 'REWORK';

export interface Person {
  id: number;
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  delta: number | null;
  epsilon: number | null;
  zeta: number | null;
  grade: Grade | null;
  weight: number | null;
  kind: Kind | null;
  verge: number | null;
  thrust: number | null;
  drift: number | null;
  momentum: number | null;
  force: number | null;
  sway: number | null;
  torque: number | null;
  pivot: number | null;
  blend: number | null;
  flux: number | null;
  crest: number | null;
  swing: number | null;
  haul: number | null;
  vector: number | null;
  phase: string | null;
  load: number | null;
  tier: string | null;
  patrons: Patron[];
  backing: number | null;
  net: number | null;
  rank: number | null;
  percentile: number | null;
  onset: string | null;
  age: number | null;
  decay: number | null;
  active: boolean;
  state: State;
  effective: number | null;
  clout: number | null;
  influence: number | null;
  brace: number | null;
  tide: number | null;
  strain: number | null;
  pulse: string | null;
  regions: string[];
  reach: number | null;
  gust: number | null;
  coil: number | null;
  allies: Ally[];
