  adjusted: number | null;
  band: string | null;
  scaled: number | null;
  thrum: number | null;
  spool: number | null;
  drag: string | null;
  lift: number | null;
  yield: number | null;
  grip: number | null;
  charge: number | null;
  churn: number | null;
  flow: number | null;
  norm: number | null;
  outlier: boolean;
  ebb: number | null;
  stray: boolean;
