  // alphabetically; absent until put in one.
  groupId: number | null;
  groupName: string | null;
  // Every group the person is in, sorted by name.
  groups: Group[];
}

// A named group of people on a sheet.
export interface Group {
  id: number;
  name: string;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
  anchor: string;
}

export type Grade = 'LOW' | 'MID' | 'HIGH';

export const GRADES: readonly Grade[] = ['LOW', 'MID', 'HIGH'];

export type Kind = 'A' | 'B' | 'C';

export const KINDS: readonly Kind[] = ['A', 'B', 'C'];

export interface Patron {
  id: number;
  name: string;
}

// An ally: a person this person follows; following is one-directional.
export interface Ally {
  id: number;
  name: string;
}

export interface NewPerson {
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  delta: number | null;
